import { readFileSync } from "node:fs";
import { join } from "node:path";
import { SKILL_ALLOWLIST } from "../skills";

const GENERATED_HEADER = `// Generated by @autumn/atmn-generator from packages/agent-docs/src/generated/skills.generated.ts.
// Do not edit — run \`bun generate\` in packages/atmn-generator instead.
`;

/** The shape agent-docs emits; only what the CLI needs is carried across. */
type AgentDocsSkill = {
	name: string;
	description: string;
	markdown: string;
	references: { path: string; contents: string }[];
};

const AGENT_DOCS_SKILLS = join(
	import.meta.dir,
	"../../../agent-docs/src/generated/skills.generated.ts",
);

const CLI_PACKAGE_JSON = join(
	import.meta.dir,
	"../../../atmn-nightly/package.json",
);

const FRONTMATTER = /^---\n([\s\S]*?)\n---\n?/;

/**
 * The CLI's version goes into each SKILL.md's frontmatter. It is what
 * `atmn skills update` compares against, and it pins the skill text to the
 * builders that same CLI version generates: an old CLI keeps old skills.
 */
const withVersion = ({
	markdown,
	version,
}: {
	markdown: string;
	version: string;
}): string => {
	const match = FRONTMATTER.exec(markdown);
	if (!match) throw new Error("skill markdown has no frontmatter");
	const fields = (match[1] ?? "")
		.split("\n")
		.filter((line) => !line.startsWith("version:"));
	return markdown.replace(
		FRONTMATTER,
		`---\n${[...fields, `version: ${version}`].join("\n")}\n---\n`,
	);
};

export const emitSkillsModule = async (): Promise<string> => {
	const { skills } = (await import(AGENT_DOCS_SKILLS)) as {
		skills: AgentDocsSkill[];
	};
	const version: string = JSON.parse(
		readFileSync(CLI_PACKAGE_JSON, "utf8"),
	).version;

	const bundled = SKILL_ALLOWLIST.map((name) => {
		const skill = skills.find((candidate) => candidate.name === name);
		if (!skill) {
			throw new Error(
				`Skill \`${name}\` is in the allowlist but agent-docs does not generate it. Available: ${skills
					.map((candidate) => candidate.name)
					.join(", ")}`,
			);
		}
		return {
			name: skill.name,
			description: skill.description,
			version,
			markdown: withVersion({ markdown: skill.markdown, version }),
			references: skill.references,
		};
	});

	return [
		GENERATED_HEADER,
		`export type BundledSkill = {
	readonly name: string;
	readonly description: string;
	/** The CLI version the skill was frozen with; the frontmatter says the same. */
	readonly version: string;
	/** Full SKILL.md text, frontmatter included. */
	readonly markdown: string;
	readonly references: readonly { readonly path: string; readonly contents: string }[];
};`,
		`export const SKILLS_VERSION = ${JSON.stringify(version)};`,
		`export const SKILLS: readonly BundledSkill[] = ${JSON.stringify(bundled, null, "\t")};`,
	].join("\n\n");
};
